CREATE SEQUENCE IF NOT EXISTS foodme.dish_addition_id_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS foodme.order_dish_addition_id_seq START WITH 1 INCREMENT BY 1;

CREATE TABLE foodme.dish_addition (
    id BIGINT NOT NULL PRIMARY KEY,
    name_en VARCHAR(255),
    name_am VARCHAR(255),
    name_ru VARCHAR(255),
    price DOUBLE PRECISION NOT NULL,
    dish_id BIGINT NOT NULL REFERENCES foodme.dish(id)
);

CREATE TABLE foodme.order_dish_addition (
    id BIGINT NOT NULL PRIMARY KEY,
    name_en VARCHAR(255),
    name_am VARCHAR(255),
    name_ru VARCHAR(255),
    price DOUBLE PRECISION NOT NULL,
    order_dish_id BIGINT NOT NULL REFERENCES foodme.order_dish(id)
);

CREATE INDEX idx_dish_addition_dish_id ON foodme.dish_addition(dish_id);
CREATE INDEX idx_order_dish_addition_order_dish_id ON foodme.order_dish_addition(order_dish_id);

SELECT setval('foodme.dish_addition_id_seq', 185);
